-- 30 minutes of silence starts a fresh chat: forget every chat whose newest message is older.
WITH stale AS (
  SELECT session_id FROM n8n_chat_histories
  GROUP BY session_id
  HAVING max(created_at) < now() - interval '30 minutes'
), forgotten AS (
  DELETE FROM n8n_chat_histories WHERE session_id IN (SELECT session_id FROM stale) RETURNING 1
)
SELECT count(*)::int AS "forgotten" FROM forgotten;

