// The agent answers {"reply","choices","listButton","customerName"}; anything else is read as plain text.
// A Chat Offer made in this message, or asked about again ("confirmOffer"), gets its Yes and No buttons (D-47).
// Limits are WhatsApp's, for reply buttons, list rows and the text above them.
const MAX_BUTTONS = 3;
const MAX_LIST_ROWS = 10;
const BUTTON_TITLE_LIMIT = 20;
const ROW_TITLE_LIMIT = 24;
const LIST_BUTTON_LIMIT = 20;
const INTERACTIVE_BODY_LIMIT = 1024;
const TEXT_LIMIT = 4096;
const NAME_LIMIT = 80;
const DEFAULT_LIST_BUTTON = 'Choose';
const DEFAULT_OFFER_CHOICES = ['Yes', 'No'];
const FOOTER_LIMIT = 60;

const gather = $('Gather').item.json;
const raw = $('Assistant Agent').item.json.output ?? '';
const waiting = $json.id ? $json : null;
const detailsBlock = $('Word Outcome').item.json.detailsBlock;
let answer;
if (raw && typeof raw === 'object') answer = raw;
else {
  let text = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  try {
    answer = JSON.parse(text);
  } catch {
    answer = { reply: String(raw) };
  }
}

const said = typeof answer.reply === 'string' && answer.reply.trim() !== ''
  ? answer.reply.trim()
  : 'Sorry, something went wrong on our side. Please ' + gather.callVenue;
const reply = detailsBlock ? said + '\n\n' + detailsBlock : said;
const clip = (text, limit) => (text.length > limit ? text.slice(0, limit - 1).trimEnd() + '…' : text);

const given = Array.isArray(answer.choices)
  ? answer.choices.filter((c) => typeof c === 'string' && c.trim() !== '').map((c) => c.trim())
  : [];
const askedOffer = waiting && (waiting.isNew || answer.confirmOffer === true) ? waiting : null;
const labels = askedOffer && given.length !== DEFAULT_OFFER_CHOICES.length ? DEFAULT_OFFER_CHOICES : given;
const idOf = (i) => (askedOffer ? 'offer-' + ['yes', 'no'][i] + '-' + askedOffer.id : 'choice-' + (i + 1));
const asButtons = labels.length <= MAX_BUTTONS;
const titles = [...new Set(labels.slice(0, MAX_LIST_ROWS).map((c) => clip(c, asButtons ? BUTTON_TITLE_LIMIT : ROW_TITLE_LIMIT)))];

let message;
if (titles.length === 0 || reply.length > INTERACTIVE_BODY_LIMIT) {
  message = { type: 'text', text: { preview_url: false, body: clip(reply, TEXT_LIMIT) } };
} else if (asButtons) {
  message = {
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: reply },
      action: { buttons: titles.map((title, i) => ({ type: 'reply', reply: { id: idOf(i), title } })) },
    },
  };
  if (askedOffer) message.interactive.footer = { text: clip(askedOffer.details.footer, FOOTER_LIMIT) };
} else {
  const listButton = typeof answer.listButton === 'string' && answer.listButton.trim() !== '' ? answer.listButton.trim() : DEFAULT_LIST_BUTTON;
  message = {
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: reply },
      action: {
        button: clip(listButton, LIST_BUTTON_LIMIT),
        sections: [{ rows: titles.map((title, i) => ({ id: 'choice-' + (i + 1), title })) }],
      },
    },
  };
}

// AST-05: only a new number's own name is saved, once.
const name = typeof answer.customerName === 'string' ? answer.customerName.trim().replace(/\s+/g, ' ') : '';
const offeredName = waiting?.isNew ? waiting.details.customerName ?? '' : '';
const customerName = gather.customer === null ? [name, offeredName].find((n) => n !== '' && n.length <= NAME_LIMIT) ?? null : null;

return { json: { message, customerName } };

// A booking made in this message still reaches the customer, with its payment details, when the reply fails.
const gather = $('Gather').item.json;
const detailsBlock = $('Word Outcome').isExecuted ? $('Word Outcome').item.json.detailsBlock : '';
const body = detailsBlock
  ? 'Booked ✅\n\n' + detailsBlock + '\n\nFor anything else, please ' + gather.callVenue
  : 'Sorry, something went wrong on our side. Please ' + gather.callVenue;
return { json: { message: { type: 'text', text: { preview_url: false, body } } } };

// D-47: what this message does to the chat's waiting Chat Offer. A tap is exact; typed words go by Offer Check.
const OFFER_TAP = /^offer-(yes|no)-(\d+)$/;
const found = $('Find Offer').item.json;
const offer = found.id ? found : null;
const tap = OFFER_TAP.exec(String($('Gather').item.json.tapId ?? ''));

let decision = 'none';
if (tap) decision = !offer ? 'gone' : Number(tap[2]) === offer.id ? tap[1] : 'stale';
else if (offer) {
  const said = $('Offer Check').isExecuted ? String($('Offer Check').item.json.text ?? '') : '';
  const word = said.toUpperCase().match(/[A-Z]+/)?.[0];
  decision = word === 'YES' ? 'yes' : word === 'NO' ? 'no' : 'other';
}
return { json: { decision, offer } };

