-- Each Chat Offer is used once: only the run that deletes it acts on it.
WITH taken AS (
  DELETE FROM assistant_chat_offers WHERE id = $1 RETURNING id, kind, details
)
SELECT taken.id, taken.kind, taken.details FROM (SELECT 1) AS one LEFT JOIN taken ON true;

