// What the agent is told about the Chat Offer, and the exact booking details added below its reply.
const CENTS_PER_RUPEE = 100;
const DEFAULT_TIME_ZONE = 'Asia/Colombo';

const gather = $('Gather').item.json;
const names = JSON.parse(gather.names);
const { decision, offer } = $('Decide').item.json;
const taken = $('Take Offer').isExecuted && $('Take Offer').item.json.id ? $('Take Offer').item.json : null;
const api = $('Book').isExecuted ? $('Book').item.json : $('Cancel Booking').isExecuted ? $('Cancel Booking').item.json : null;

const money = (m) => m.currency + ' ' + (m.amount / CENTS_PER_RUPEE).toLocaleString('en-US', { maximumFractionDigits: 2 });
const zoneOf = (venueId) => names.venues[venueId]?.timeZone ?? DEFAULT_TIME_ZONE;
const time = (iso, zone) => new Date(iso).toLocaleTimeString('en-GB', { timeZone: zone, hour: 'numeric', minute: '2-digit', hour12: true });
const shortDay = (iso, zone) => new Date(iso).toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' });
const sameDay = (a, b, zone) => shortDay(a, zone) === shortDay(b, zone);

const reach = 'give the way to reach a person';
let news;
let detailsBlock = '';

function bookingBlock(booking) {
  const zone = zoneOf(booking.venueId);
  const resource = names.resources[booking.resourceId];
  const venue = names.venues[booking.venueId];
  const lines = [
    '*' + (resource?.name ?? 'Booking') + (venue ? ', ' + venue.name : '') + '*',
    shortDay(booking.startsAt, zone) + ', ' + time(booking.startsAt, zone) + ' – ' + time(booking.endsAt, zone),
  ];
  if (booking.status === 'AWAITING_PAYMENT' && booking.expiresAt) {
    const today = sameDay(booking.expiresAt, new Date().toISOString(), zone);
    const by = time(booking.expiresAt, zone) + (today ? ' today' : ', ' + shortDay(booking.expiresAt, zone));
    lines.push('Pay *' + money(booking.amountDue) + '* by ' + by);
    const bank = booking.bankAccount;
    if (bank) lines.push(bank.bankName + (bank.branch ? ', ' + bank.branch : ''), bank.accountName, bank.accountNumber);
  } else {
    lines.push('Confirmed · ' + money(booking.price) + ' to pay at the venue');
  }
  return lines.join('\n');
}

function afterBooking() {
  const { statusCode, body } = api;
  if (api.error || !body || statusCode >= 500) {
    return 'The customer said yes, but booking failed for a technical reason, so NOTHING was booked. Say sorry, that you can\'t book right now, and ' + reach + '.';
  }
  if (statusCode < 300) {
    const booking = body.data;
    detailsBlock = bookingBlock(booking);
    if (booking.status === 'AWAITING_PAYMENT') {
      return 'Just done: the customer said yes and the booking was made (' + taken.details.summary + '). It waits for payment: ' +
        money(booking.amountDue) + ' by bank transfer before the time shown below your reply, or it expires. ' +
        'The booking, amount, time limit and bank account are added below your reply word for word, so don\'t repeat the account details. ' +
        'Tell them it\'s booked and held for them until then, but not confirmed until the venue accepts their payment; to transfer the amount by that time, and that sending the receipt photo in this chat comes soon; until then they ' +
        'send it on the Customer Portal or call the venue.';
    }
    return 'Just done: the customer said yes and the booking was made and confirmed (' + taken.details.summary + '). The venue is Pay at Venue: nothing to pay now, they pay at the venue. The booking is added below your reply.';
  }
  const why = body.message ?? 'refused';
  switch (body.code) {
    case 'tt_bkg_002':
      return 'The customer said yes, but NOTHING was booked: someone else just took that time (' + taken.details.summary + '). Say sorry, use find_free_times for the same date near that time, and offer the nearest free times as choices.';
    case 'tt_bkg_012':
      return 'The customer said yes, but NOTHING was booked: the price changed (' + why + '). Tell them the new price and, if they still want it, call offer_booking again so they can confirm the new price.';
    case 'tt_bkg_003':
      return 'The customer said yes, but NOTHING was booked: they already have a booking waiting for payment. They pay for it first, or cancel it (my_bookings, then offer_cancel).';
    case 'tt_bkg_005':
      return 'The customer said yes, but NOTHING was booked: their name isn\'t saved yet. Ask for their name; then make the Chat Offer again.';
    default:
      return 'The customer said yes, but NOTHING was booked: ' + why + '. Explain kindly and offer to look for another time.';
  }
}

function afterCancelling() {
  const { statusCode, body } = api;
  if (api.error || !body || statusCode >= 500) {
    return 'The customer said yes, but cancelling failed for a technical reason, so the booking is NOT cancelled. Say sorry and ' + reach + '.';
  }
  if (statusCode < 300) {
    const booking = body.data;
    const refund = booking.paid.amount > 0 ? ' They had paid ' + money(booking.paid) + '; a refund is up to the venue, so give the venue\'s phone for it.' : '';
    return 'Just done: the customer said yes and the booking is cancelled (' + taken.details.summary.replace(/^cancel /, '') + '). The time is free again.' + refund;
  }
  return 'The customer said yes, but the booking is NOT cancelled: ' + (body.message ?? 'refused') + '. Explain kindly; if a phone number is given, pass it on.';
}

const waitingNow = (o) => 'A Chat Offer is waiting for the customer\'s yes: ' + o.details.summary + '.';

if (decision === 'none') news = 'No Chat Offer is waiting for the customer\'s yes.';
else if (decision === 'other') {
  news = waitingNow(offer) + ' This message doesn\'t accept it. If they want something changed, make a new Chat Offer with the change. ' +
    'If they asked something, answer and then ask again about the offer, with the Yes and No choices.';
} else if (decision === 'stale') {
  news = 'The customer tapped a button of an older Chat Offer that was replaced, so nothing was done. ' + waitingNow(offer) + ' Ask about this one.';
} else if (decision === 'gone' || !taken) {
  news = 'The customer answered a Chat Offer that ran out or was already used, so nothing was done this time. Check my_bookings before saying what they have, and offer again if they still want it.';
} else if (decision === 'no') {
  news = 'The customer said no to the Chat Offer (' + taken.details.summary + '), so it\'s dropped and nothing changed. Ask what they\'d like instead.';
} else if (taken.kind === 'book') news = afterBooking();
else if (taken.kind === 'cancel') news = afterCancelling();
else news = 'The customer said yes to a Chat Offer this Assistant can\'t carry out, so nothing changed. Say sorry and ' + reach + '.';

return { json: { offerNews: news, detailsBlock } };
